public class Main {
    static int n, k;
    static long[] a, tails;
    static int[] removedAt;

    // Whether the tiles still present after t removals have an LIS of length at least k.
    static boolean feasible(int t) {
        int len = 0;
        for (int i = 0; i < n; i++) {
            if (removedAt[i] <= t) continue;
            int lo = 0, hi = len;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < a[i]) lo = mid + 1; else hi = mid;
            }
            tails[lo] = a[i];
            if (lo == len) len++;
        }
        return len >= k;
    }

    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        n = r.nextInt();
        k = r.nextInt();
        a = new long[n];
        tails = new long[n];
        removedAt = new int[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        for (int time = 1; time <= n; time++) removedAt[r.nextInt()] = time;
        if (!feasible(0)) { System.out.println(-1); return; }
        int low = 0, high = n + 1;
        while (low + 1 < high) {
            int mid = (low + high) / 2;
            if (feasible(mid)) low = mid; else high = mid;
        }
        System.out.println(low);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	n, k := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	removedAt := make([]int, n)
	for time := 1; time <= n; time++ {
		removedAt[readInt()] = time
	}
	tails := make([]int, 0, n)
	// Whether the tiles still present after t removals have an LIS of length at least k.
	feasible := func(t int) bool {
		tails = tails[:0]
		for i, v := range a {
			if removedAt[i] <= t {
				continue
			}
			pos := sort.SearchInts(tails, v)
			if pos == len(tails) {
				tails = append(tails, v)
			} else {
				tails[pos] = v
			}
		}
		return len(tails) >= k
	}
	if !feasible(0) {
		fmt.Println(-1)
		return
	}
	low, high := 0, n+1
	for low+1 < high {
		mid := (low + high) / 2
		if feasible(mid) {
			low = mid
		} else {
			high = mid
		}
	}
	fmt.Println(low)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
